import SwiftUI

/// Reserve a per-site alias bound to one of the active persona's logins. The
/// alias's local-part is generated by the repository (random, anti-correlation);
/// this sheet only picks the login to bind. Pre-relay it's a reservation only.
struct AliasEditorSheet: View {
    @Environment(AppEnvironment.self) private var env
    @Environment(\.dismiss) private var dismiss
    let persona: Persona
    @State private var selectedItemId: String?

    /// Logins scoped to the active persona's Space (falls back to all logins when
    /// the persona pins no Space) — never surfaces another persona's items.
    private var loginItems: [VaultItem] {
        env.repository.items.filter { item in
            item.category == .login
                && (persona.primarySpaceID == nil || item.folderId == persona.primarySpaceID)
        }
    }

    var body: some View {
        NavigationStack {
            Form {
                if loginItems.isEmpty {
                    Section { Text("No logins to bind yet.").themedForeground(.secondary) }
                } else {
                    Section("Choose a login") {
                        Picker("Login", selection: $selectedItemId) {
                            Text("None").tag(String?.none)
                            ForEach(loginItems) { item in
                                Text(item.title).tag(String?.some(item.id))
                            }
                        }
                    }
                }
                Section {
                    if let target = env.repository.identityUsername(forPersona: persona) {
                        LabeledContent { Text(target).themedForeground(.secondary) }
                            label: { Text("Forwards to") }
                    }
                } footer: {
                    Text("Replies from your destination inbox may reveal your real email address.")
                }
            }
            .navigationTitle(Text("New per-site alias"))
            .toolbar {
                ToolbarItem(placement: .cancellationAction) { Button("Cancel") { dismiss() } }
                ToolbarItem(placement: .confirmationAction) {
                    Button("Save") { save() }.disabled(selectedItemId == nil)
                }
            }
        }
    }

    private func save() {
        guard let itemId = selectedItemId else { return }
        _ = try? env.repository.createPerSiteAlias(for: persona, boundItemId: itemId)
        dismiss()
    }
}
